import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class ComparableDemo {
    static class Employee implements Comparable<Employee> {
        final int id;
        final String name;
        final double salary;

        Employee(int id, String name, double salary) {
            this.id = id;
            this.name = name;
            this.salary = salary;
        }

        // Natural order: Primary by salary descending; Secondary by id ascending
        @Override
        public int compareTo(Employee other) {
            // SAFE: Use Double.compare to avoid numeric overflow / NaN issues!
            int salaryCmp = Double.compare(other.salary, this.salary); // Descending
            if (salaryCmp != 0) return salaryCmp;
            return Integer.compare(this.id, other.id); // Ascending tie-breaker
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Employee)) return false;
            Employee e = (Employee) o;
            return id == e.id && Double.compare(e.salary, salary) == 0 && Objects.equals(name, e.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, name, salary);
        }

        @Override
        public String toString() {
            return String.format("[%s: id=%d, $%.0f]", name, id, salary);
        }
    }

    public static void main(String[] args) {
        List<Employee> roster = new ArrayList<>();
        roster.add(new Employee(103, "Charlie", 85000));
        roster.add(new Employee(101, "Alice", 95000));
        roster.add(new Employee(102, "Bob", 85000));

        // Sorts using natural ordering (Comparable)
        Collections.sort(roster);

        System.out.println("Sorted Roster (Highest Salary First):");
        for (Employee e : roster) {
            System.out.println(" -> " + e);
        }
    }
}
// Expected Output:
// Sorted Roster (Highest Salary First):
//  -> [Alice: id=101, $95000]
//  -> [Bob: id=102, $85000]
//  -> [Charlie: id=103, $85000]

