import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class SemanticVersion implements Comparable<SemanticVersion> {
    final int major;
    final int minor;
    final int patch;

    public SemanticVersion(int major, int minor, int patch) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
    }

    @Override
    public int compareTo(SemanticVersion o) {
        int cmp = Integer.compare(this.major, o.major);
        if (cmp != 0) return cmp;
        cmp = Integer.compare(this.minor, o.minor);
        if (cmp != 0) return cmp;
        return Integer.compare(this.patch, o.patch);
    }

    @Override
    public String toString() { return major + "." + minor + "." + patch; }

    public static void main(String[] args) {
        List<SemanticVersion> versions = new ArrayList<>(List.of(
            new SemanticVersion(2, 1, 0),
            new SemanticVersion(1, 9, 5),
            new SemanticVersion(2, 0, 1),
            new SemanticVersion(2, 1, 4)
        ));

        Collections.sort(versions);
        System.out.println("Sorted versions: " + versions);
    }
}

