import java.util.List;
import java.util.ArrayList;

public class Product implements Comparable<Product> {
    final String sku;
    final double price;

    public Product(String sku, double price) {
        this.sku = sku;
        this.price = price;
    }

    @Override
    public int compareTo(Product o) {
        if (this.sku == null && o.sku == null) return 0;
        if (this.sku == null) return -1;
        if (o.sku == null) return 1;
        return this.sku.compareTo(o.sku);
    }

    @Override
    public String toString() { return sku; }

    public static void main(String[] args) {
        List<Product> prods = new ArrayList<>(List.of(
            new Product("PROD-Z", 10.0),
            new Product("PROD-A", 50.0),
            new Product("PROD-M", 20.0)
        ));
