public class ConsistencyAuditor {
    public static <T extends Comparable<T>> boolean isConsistentWithEquals(T a, T b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        boolean compareZero = a.compareTo(b) == 0;
        boolean equalsTrue = a.equals(b);
        return compareZero == equalsTrue;
    }

    public static void main(String[] args) {
        String s1 = "hello";
        String s2 = "hello";
        System.out.println(isConsistentWithEquals(s1, s2));

        java.math.BigDecimal b1 = new java.math.BigDecimal("2.0");
        java.math.BigDecimal b2 = new java.math.BigDecimal("2.00");
        System.out.println(isConsistentWithEquals(b1, b2));
    }
}

