public class BoundaryClamper {
    public static <T extends Comparable<T>> T clampComparable(T val, T lower, T upper) {
        if (val.compareTo(lower) < 0) return lower;
        if (val.compareTo(upper) > 0) return upper;
        return val;
    }

    public static void main(String[] args) {
        System.out.println(clampComparable(5, 10, 20));
        System.out.println(clampComparable(15, 10, 20));
        System.out.println(clampComparable(25, 10, 20));
    }
}
